import { Component, Input, ChangeDetectionStrategy } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-avatar',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './avatar.component.html',
  styleUrls: ['./avatar.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class AvatarComponent {
  @Input() name: string = '';
  @Input() size: number = 40;
  @Input() imageUrl?: string;

  get initials(): string {
    if (!this.name) return '?';
    const chars = this.name.trim();
    // For Japanese names, take first character
    // For English names, take first letter of first and last name
    if (/[\u3000-\u9fff]/.test(chars)) {
      return chars.charAt(0);
    }
    const parts = chars.split(/\s+/);
    if (parts.length >= 2) {
      return (parts[0].charAt(0) + parts[parts.length - 1].charAt(0)).toUpperCase();
    }
    return chars.charAt(0).toUpperCase();
  }

  get backgroundColor(): string {
    const colors = [
      '#e53935', '#d81b60', '#8e24aa', '#5e35b1',
      '#3949ab', '#1e88e5', '#039be5', '#00acc1',
      '#00897b', '#43a047', '#7cb342', '#c0ca33',
      '#fdd835', '#ffb300', '#fb8c00', '#f4511e',
    ];
    let hash = 0;
    for (let i = 0; i < this.name.length; i++) {
      hash = this.name.charCodeAt(i) + ((hash << 5) - hash);
    }
    return colors[Math.abs(hash) % colors.length];
  }
}
